use std::{
    collections::BTreeMap,
    io,
    path::{Path, PathBuf},
};

/// 资源文件类型
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum AssetType {
    /// 图片资源（png, jpg, webp 等）
    Image,
    /// 音频资源（mp3, ogg, wav 等）
    Audio,
    /// 视频资源（mp4, webm 等）
    Video,
    /// 脚本资源（.ring 等）
    Script,
    /// 其他无法识别的资源类型
    Other,
}

/// 文件系统中的变更事件类型
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FileEvent {
    /// 文件被创建
    Created,
    /// 文件内容被修改
    Modified,
    /// 文件被删除
    Deleted,
}

/// 单个资源条目的元信息
#[derive(Debug, Clone)]
pub struct AssetEntry {
    /// 资源文件的绝对路径
    pub absolute_path: PathBuf,
    /// 相对于 assets/ 根目录的路径
    pub relative_path: String,
    /// 文件大小（字节）
    pub file_size: u64,
    /// 资源类型
    pub asset_type: AssetType,
}

/// 项目资源索引，维护 assets/ 目录下所有资源的元信息
#[derive(Debug, Clone)]
pub struct AssetIndex {
    /// 按相对路径索引的所有资源条目
    entries: BTreeMap<String, AssetEntry>,
    /// 按资源类型分组的相对路径列表
    by_type: BTreeMap<AssetType, Vec<String>>,
}

